; Sprint: a small ladder cell for CellHack2.  GENERATED by cells/gen_sprint.py -- do not edit by hand.
; Written with AI help.
;
; Paste this whole file into the site.  It has no org/bits/section/%include on purpose: the server
; prepends `bits 64 / org CODE_BASE / default rel / <cellhack.inc>` and runs `nasm -f bin`.
; CPU target: plain qemu64 (SSE2 only used).  No memory writes, no loops, no stack use.
;
; Behaviour
;   1. An enemy next to me: bite it.  One enemy: that one.  Two or four: first of DOWN, LEFT, UP, RIGHT.
;      Exactly three: the one opposite the single non-enemy side.
;   2. Otherwise split when energy >= threshold, else rest.  Threshold = 5, but 16 while an enemy
;      is anywhere in the 5x5 view, and 5 again from tick 2980 on.  The split goes to the first
;      empty adjacent square of DOWN, RIGHT, UP, LEFT; with none empty it rests.
;      (Evaluated as: e < 5 rest; no enemy in view split; e >= 16 split; tick >= 2980 split;
;      else rest.  Same decisions as the threshold rule, fewer instructions on the common paths.)
;
; Instruction counts per path (every executed instruction, including taken jumps and ret;
; in brackets the same path with taken jumps not counted -- the indirect jmp counts as a taken jump):
;   bite (any adjacent enemy)                               6  (5)
;   rest, e < 5                                          8  (6)
;   split/rest-by-table, no enemy in view, e >= 5         19 (18)
;   rest, enemy in view, 5 <= e < 16, tick < 2980          20 (18)
;   split/rest-by-table, enemy in view, e >= 16          21 (18)
;   split/rest-by-table, enemy in view, 5 <= e < 16, late  23 (20)

start:
	movdqu		xmm0, [rdi + VIEW_CELLS + VIEW_UP]	; view idx 7..22
	pcmpeqb		xmm0, [kEnemy]
	pmovmskb	eax, xmm0			; bits 0 UP, 4 LEFT, 6 RIGHT, 10 DOWN
	jmp		[abs fight_tbl + rax*8]		; mask 0 -> slow

eat_up:
	mov		al, ACT_EAT + DIR_UP
	ret
eat_right:
	mov		al, ACT_EAT + DIR_RIGHT
	ret
eat_down:
	mov		al, ACT_EAT + DIR_DOWN
	ret
eat_left:
	mov		al, ACT_EAT + DIR_LEFT
	ret

slow:						; 4 instructions so far
	cmp		esi, SPLIT_MIN
	jb		rest
	movdqu		xmm1, [rdi + VIEW_CELLS]	; view idx 0..15
	movdqu		xmm2, [rdi + VIEW_CELLS + 9]	; view idx 9..24
	pcmpeqb		xmm1, [kTwoLo]			; lane 12 (self) never matches
	pcmpeqb		xmm2, [kTwoHi]			; lane 3 (self) never matches
	por		xmm1, xmm2
	pmovmskb	eax, xmm1
	test		eax, eax
	jnz		threat
split:
	movdqu		xmm0, [rdi + VIEW_CELLS + VIEW_UP]
	pcmpeqb		xmm0, [kEmpty]
	pmovmskb	eax, xmm0			; bits set = empty adjacent squares
	mov		al, [abs split_tbl + rax]	; mask 0 -> ACT_REST
	ret
threat:
	cmp		esi, 16
	jae		split
	cmp		dword [rdi + VIEW_TICK], 2980
	jae		split
rest:
	mov		al, ACT_REST
	ret
stub:						; unreachable fight_tbl entries
	xor		eax, eax
	ret

; ---- constants (legacy-SSE memory operands must be 16-byte aligned)
	align 16
kEnemy:	db 0x02, 0xff, 0xff, 0xff, 0x02, 0xff, 0x02, 0xff, 0xff, 0xff, 0x02, 0xff, 0xff, 0xff, 0xff, 0xff	; 2 at UP/LEFT/RIGHT/DOWN lanes
kEmpty:	db 0x00, 0xff, 0xff, 0xff, 0x00, 0xff, 0x00, 0xff, 0xff, 0xff, 0x00, 0xff, 0xff, 0xff, 0xff, 0xff	; 0 at UP/LEFT/RIGHT/DOWN lanes
kTwoLo:	db 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0xff, 0x02, 0x02, 0x02	; idx 0..15, self (lane 12) excluded
kTwoHi:	db 0x02, 0x02, 0x02, 0xff, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02	; idx 9..24, self (lane 3) excluded

; ---- fight_tbl: 1106 qwords, index = adjacent-enemy mask
	align 8
fight_tbl:

	dq slow		; mask 0x000
	dq eat_up		; mask 0x001
	times 14 dq stub
	dq eat_left		; mask 0x010
	dq eat_left		; mask 0x011
	times 46 dq stub
	dq eat_right		; mask 0x040
	dq eat_up		; mask 0x041
	times 14 dq stub
	dq eat_left		; mask 0x050
	dq eat_up		; mask 0x051
	times 942 dq stub
	dq eat_down		; mask 0x400
	dq eat_down		; mask 0x401
	times 14 dq stub
	dq eat_down		; mask 0x410
	dq eat_left		; mask 0x411
	times 46 dq stub
	dq eat_down		; mask 0x440
	dq eat_right		; mask 0x441
	times 14 dq stub
	dq eat_down		; mask 0x450
	dq eat_down		; mask 0x451
fight_tbl_end:

; ---- split_tbl: 1106 bytes, index = empty-adjacent mask
split_tbl:
	db 0x01		; mask 0x000
	db 0x20		; mask 0x001
	times 14 db 0x01
	db 0x23		; mask 0x010
	db 0x20		; mask 0x011
	times 46 db 0x01
	db 0x21		; mask 0x040
	db 0x21		; mask 0x041
	times 14 db 0x01
	db 0x21		; mask 0x050
	db 0x21		; mask 0x051
	times 942 db 0x01
	db 0x22		; mask 0x400
	db 0x22		; mask 0x401
	times 14 db 0x01
	db 0x22		; mask 0x410
	db 0x22		; mask 0x411
	times 46 db 0x01
	db 0x22		; mask 0x440
	db 0x22		; mask 0x441
	times 14 db 0x01
	db 0x22		; mask 0x450
	db 0x22		; mask 0x451
split_tbl_end:
